SELECT ?z ?label ?sensor WHERE {
  ?z a brick:Zone ; rdfs:label ?label .
  FILTER (?label LIKE "%mid%" || ?label LIKE "%Zone%")
  ?z brick:hasPoint ?sensor .
}

SELECT ?room ?sensor ?ref WHERE {
  brick:Zone ?z .
  ?z rdfs:label ?lbl .
  FILTER (str(?lbl) LIKE "Core%")
  ?z brick:hasPart ?room .
  ?room brick:hasPoint ?sensor .
  ?sensor brick:isPointOf ?room .
  ?sensor a brick:Air_Temperature_Sensor .
  OPTIONAL { ?sensor ref:hasExternalReference ?ref }
}

SELECT ?room ?sensor ?ref WHERE {
  ?z a brick:Zone ; rdfs:label "Core_mid" .
  ?z brick:hasPart ?room .
  ?room brick:hasPoint ?sensor .
  ?sensor a brick:Air_Temperature_Sensor .
  OPTIONAL { ?sensor ref:hasExternalReference ?ref }
}

